from typing import List

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        ans = 0
        for left in range(len(nums)):
            odds = 0
            for right in range(left, len(nums)):
                odds += nums[right] % 2
                if odds == k:
                    ans += 1
                elif odds > k:
                    break
        return ans

