from typing import List

class Solution:
    def numberOfSubarrays(self, nums: List[int], k: int) -> int:
        def at_most(limit: int) -> int:
            left = odds = total = 0
            for right, value in enumerate(nums):
                odds += value % 2
                while odds > limit:
                    odds -= nums[left] % 2
                    left += 1
                total += right - left + 1
            return total

        return at_most(k) - at_most(k - 1)

